record.field:
website = env.ref('beauty_parlor.website_industry')
to_deactivate = [ 'portal.user_sign_in', 'website.footer_custom', 'website.header_search_box', 'website.header_text_element', 'website.template_header_default', 'website.homepage', 'website.contactus', ] to_activate = [ 'website.footer_no_copyright', 'website.header_call_to_action', 'website.header_social_links', 'website.option_header_disclaimer', 'website.template_footer_centered', 'website.template_header_vertical', 'website.template_header_vertical_align_center', ]
ctx = {'website_id': website.id}
for xml_id in to_deactivate: env.ref(xml_id).with_context(**ctx).write({'active': False}) for xml_id in to_activate: env.ref(xml_id).with_context(**ctx).write({'active': True})
menus = env['website.menu'] base_domain = [('website_id', '=', website.id), ('parent_id', '=', website.menu_id.id)]
# Menu items of the design, in navbar order (created if no installed module # provides them). design_menus = [ ('Home', '/', 0), ('Services', '/our-services', 10), ('Contact Us', '/contactus', 20), ]
# Default menu items to remove menus.search(base_domain + [('url', 'in', ['/appointment', '/event', '/shop'])]).unlink()
for name, url, sequence in design_menus: menu = menus.search(base_domain + [('url', '=', url)], limit=1) if menu: menu.write({'name': name, 'sequence': sequence}) else: menus.create({ 'name': name, 'url': url, 'sequence': sequence, 'parent_id': website.menu_id.id, 'website_id': website.id, })
